import (
	"fmt"
)

resp, err := client.OrderCustomFields().ListOrderCustomFields(ctx, map[string]any{"sort": "label", "dir": "asc"}, nil)
if err != nil {
	log.Fatal(err)
}
body := resp.Map().(map[string]any)
for _, row := range body["order_custom_fields"].([]any) {
	field := row.(map[string]any)
	fmt.Println(field["id"], field["label"], field["field_type"])
}
pagination := body["pagination"].(map[string]any)
fmt.Println(pagination["total"], pagination["has_next"])

